{{
  (() => {
    const raw = qGetCategoryTotals.data;
    const rows = Array.isArray(raw)
      ? raw
      : raw
      ? Object.values(raw)
      : [];

    const total = rows.reduce((sum, r) => sum + (r.count || 0), 0);

    const parts = [];

    // Total first — with extra spacing after it
    parts.push(
      `<span>Total:</span> <span style="color:#1E90FF; font-weight:600;">${total}</span>`
    );

    // Each category
    parts.push(
      ...rows.map(
        r =>
          `<span>${r.category}:</span> <span style="color:#1E90FF;">${r.count}</span>`
      )
    );

    // Join with extra spacing — more than before
    return parts.join("&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;");
  })()
}}
